// CSV ingest: parse rows and infer column types
const rows="name,age\\nana,30\\nbo,25".trim().split('\n').map(r=>r.split(','));
const head=rows[0];
const types=head.map((_,i)=>rows.slice(1).every(r=>r[i]!==undefined&&r[i]!==''&&!isNaN(+r[i]))?'number':'string');
console.log('columns:',head.map((h,i)=>h+':'+types[i]).join(', '),'| rows:',rows.length-1);

